cat > src/orchestration/turnUsageContract.test.ts <<'EOF'
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {TurnUsageMetadata} from '../index.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// specs/hal-engine-config-hooks/spec.md#9
it('exposes the turn usage total to the response hook', async () => {
  const provider: AIProvider = {
    async *sendMessage() {
      yield {type: 'stop' as const, stopReason: 'end_turn', usage: {inputTokens: 3, outputTokens: 2, totalTokens: 5}};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  let total: TurnUsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), undefined, {
    hooks: {afterModelResponse: async (_session, _text, usage) => { total = usage; }},
  });
  const session: ChatSession = {
    sessionId: 's', userId: 'u', entries: [{role: 'user', content: 'Go', timestamp: '2026-01-01T00:00:00.000Z'}],
  };

  await orchestrator.processMessage(session);

  expect(total).toEqual({inputTokens: 3, outputTokens: 2, totalTokens: 5});
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/turnUsageContract.test.ts"

